INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('where-the-caravans-set-forth', 'جہاں سے قافلے چلے', 'ur', 'history', '<p>A faithful English reading edition of an Urdu work on the sacred geography and early history of Mecca and Medina, assembled from the Articulator GPT translation supplied for local review. This review copy has no podcast episodes; it is prepared for reading and chapter read-aloud.</p>', NULL, NULL, 'where-the-caravans-set-forth/book.pdf', '2026-08-16T20:07:29Z', 'caf3fe520cc826e1026d4ffa868eb58e2d8ce8bb');
