INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 28, NULL, 'Fatimah''s house stood near the dwelling of the Messenger of God. Ali lived there with her. After the Prophet''s death, the family remained in that same area. The distances were very small.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'fatimahs house stood near the dwelling of the messenger of god ali lived there with her after the prophets death the family remained in that same area the distances were very small', '');
