INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 48, NULL, 'The reports concerning Fatimah''s house are among the most painful in Muslim history. Some sources speak of threats to burn the house. Others report force being used at the door. Shia sources preserve the further claim that Fatimah was injured and that the injuries contributed to her death.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'the reports concerning fatimahs house are among the most painful in muslim history some sources speak of threats to burn the house others report force being used at the door shia sources preserve the further claim that fatimah was injured and that the injuries contributed to her death', '');
