INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 52, NULL, 'Reports found even in major Sunni collections state that she remained angry with Abu Bakr over the dispute concerning her inheritance and Fadak and did not speak to him until her death.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'reports found even in major sunni collections state that she remained angry with abu bakr over the dispute concerning her inheritance and fadak and did not speak to him until her death', '');
