INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 62, NULL, 'I was walking near the old cemetery when I saw a Pakistani family. An elderly man was with them, and they were trying to locate a particular grave.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'i was walking near the old cemetery when i saw a pakistani family an elderly man was with them and they were trying to locate a particular grave', '');
