INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 64, NULL, 'I told them that the matter was disputed and that no one could point with certainty to a single grave in al-Baqi and say, “This is unquestionably hers.”', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'i told them that the matter was disputed and that no one could point with certainty to a single grave in al baqi and say this is unquestionably hers', '');
