INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 70, NULL, 'The family became frightened and left.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'the family became frightened and left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 71, NULL, 'I remained disturbed.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'i remained disturbed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 72, NULL, 'Why should a historical question create such anxiety?', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'why should a historical question create such anxiety', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 73, NULL, 'If a grave is uncertain, it is uncertain. Acknowledging that does not diminish anyone''s faith.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'if a grave is uncertain it is uncertain acknowledging that does not diminish anyones faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 74, NULL, 'On the contrary, the uncertainty itself may preserve an important truth.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'on the contrary the uncertainty itself may preserve an important truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 75, NULL, 'Fatimah wanted her burial place concealed.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'fatimah wanted her burial place concealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 76, NULL, 'That concealment was a final statement.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'that concealment was a final statement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 77, NULL, 'It said that something had happened between her and the ruling authorities that she did not wish to be forgotten.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'it said that something had happened between her and the ruling authorities that she did not wish to be forgotten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 78, NULL, 'When people erase that conflict from history and reduce the matter to a simple question of where a grave lies, they miss the larger meaning.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'when people erase that conflict from history and reduce the matter to a simple question of where a grave lies they miss the larger meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 79, NULL, 'A grave can be hidden, but history cannot be buried so easily.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'a grave can be hidden but history cannot be buried so easily', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 80, NULL, 'Later I walked through the area again.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'later i walked through the area again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 81, NULL, 'The old houses had largely disappeared. Great extensions of the mosque had covered ground once occupied by lanes, courtyards, and family dwellings. The city looked magnificent, but much of the older Medina had vanished beneath the marble.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'the old houses had largely disappeared great extensions of the mosque had covered ground once occupied by lanes courtyards and family dwellings the city looked magnificent but much of the older medina had vanished beneath the marble', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 82, NULL, 'This is the paradox of sacred cities.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'this is the paradox of sacred cities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 83, NULL, 'As they expand to accommodate millions, the physical traces of their earliest history disappear.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'as they expand to accommodate millions the physical traces of their earliest history disappear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 84, NULL, 'Visitors gain space, comfort, and safety, but they lose the old scale of the city.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'visitors gain space comfort and safety but they lose the old scale of the city', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 85, NULL, 'To understand what happened here, one must therefore read, walk, compare, and ask questions.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'to understand what happened here one must therefore read walk compare and ask questions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 86, NULL, 'One must also be willing to live with uncertainty where the evidence does not permit certainty.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'one must also be willing to live with uncertainty where the evidence does not permit certainty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 87, NULL, 'The burial place of Fatimah is such a case.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'the burial place of fatimah is such a case', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 88, NULL, 'What remains certain is her dignity, her closeness to the Messenger of God, her grief after his death, her conflict with the new political order, and the secrecy of her burial.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'what remains certain is her dignity her closeness to the messenger of god her grief after his death her conflict with the new political order and the secrecy of her burial', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the burial place of fatimah, daughter of the messenger of god', '14. The Burial Place of Fatimah, Daughter of the Messenger of God', 89, NULL, 'Those facts should not be lost.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 14 the burial place of fatimah daughter of the messenger of god', 'those facts should not be lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 0, NULL, 'As for the previous day, I had wanted to see several places together, but in such a way that I could spend a good deal of time there, because the following day I was to leave Madinah for Khaybar and then proceed toward Fadak.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'as for the previous day i had wanted to see several places together but in such a way that i could spend a good deal of time there because the following day i was to leave madinah for khaybar and then proceed toward fadak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 1, NULL, 'Early in the morning, I left my hotel and, emerging from the southern side of Masjid al-Nabawi, passed through the lanes of old Madinah until I reached the route known as Darb al-Sunnah. When the Messenger of God came from Quba and entered Madinah, he had travelled by this very route. It is therefore also called Darb al-Rasul. The route is about four and a half kilometres long. It has now been developed into an attractive pedestrian track, and small vehicles also operate along it. Elderly people, or those who find walking difficult, can use these little vehicles. They run on electric batteries and therefore make no noise. Most people are unaware of this route.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'early in the morning i left my hotel and emerging from the southern side of masjid al nabawi passed through the lanes of old madinah until i reached the route known as darb al sunnah when the messenger of god came from quba and entered madinah he had travelled by this very route it is therefore also called darb al rasul the route is about four and a half kilometres long it has now been developed into an attractive pedestrian track and small vehicles also operate along it elderly people or those who find walking difficult can use these little vehicles they run on electric batteries and therefore make no noise most people are unaware of this route', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 2, NULL, 'Along the way stands a fort where the chief of Banu Najjar once lived. It is now being renovated. Banu Najjar were the maternal relatives of the Messenger of God, so this entire area was, in a sense, the neighbourhood of his maternal kin. I walked around the fort once, but every route leading inside was closed. Arab forts are generally elevated and enclosed on every side. The outer walls contain only very small windows, and in some places there are narrow slits or openings. Travelling along this route, I stopped at various places and tried to imagine the historical scenes that had existed in the time of the Messenger of God.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'along the way stands a fort where the chief of banu najjar once lived it is now being renovated banu najjar were the maternal relatives of the messenger of god so this entire area was in a sense the neighbourhood of his maternal kin i walked around the fort once but every route leading inside was closed arab forts are generally elevated and enclosed on every side the outer walls contain only very small windows and in some places there are narrow slits or openings travelling along this route i stopped at various places and tried to imagine the historical scenes that had existed in the time of the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 3, NULL, 'This is also the route by which one can reach the Well of Ghars. After travelling about four kilometres, I turned toward Bir Ghars. Ghars is a large well whose water is sweet and clear. Around it is a mechanism by which water used to be drawn, while on one side there is also a place from which water could be drawn with a water-skin. The well, however, was used more for meeting the needs of crops and date groves than for drinking. There was therefore also an arrangement for drawing water by animal power. The camel performed the same kinds of tasks that oxen do in our Punjab, such as ploughing and watering fields.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'this is also the route by which one can reach the well of ghars after travelling about four kilometres i turned toward bir ghars ghars is a large well whose water is sweet and clear around it is a mechanism by which water used to be drawn while on one side there is also a place from which water could be drawn with a water skin the well however was used more for meeting the needs of crops and date groves than for drinking there was therefore also an arrangement for drawing water by animal power the camel performed the same kinds of tasks that oxen do in our punjab such as ploughing and watering fields', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 4, NULL, 'The place where this well stands was once a Jewish area. A fort belonging to the Jewish tribe of Banu Qurayzah stood directly opposite it. A ring road has now been built between this well and the former settlement of Banu Qurayzah. Today the marks left by the hoofs of camels can still be seen there. I photographed them.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the place where this well stands was once a jewish area a fort belonging to the jewish tribe of banu qurayzah stood directly opposite it a ring road has now been built between this well and the former settlement of banu qurayzah today the marks left by the hoofs of camels can still be seen there i photographed them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 5, NULL, 'When the Messenger of God arrived during the Hijrah and stayed at Quba, water from this well was brought for him to drink. The Messenger of God greatly liked the water of this well. At that time there were many wells in Madinah whose water was used for drinking, bathing, and washing clothes and utensils. Because of the high mineral content, however, the water of those wells was somewhat saline. This was naturally difficult for a person newly arrived in Madinah, whereas the water of this well was sweet.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'when the messenger of god arrived during the hijrah and stayed at quba water from this well was brought for him to drink the messenger of god greatly liked the water of this well at that time there were many wells in madinah whose water was used for drinking bathing and washing clothes and utensils because of the high mineral content however the water of those wells was somewhat saline this was naturally difficult for a person newly arrived in madinah whereas the water of this well was sweet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 6, NULL, 'At that time Madinah was a city surrounded, both within and without, by orchards. The entire region was filled with date palms, which is why it was known as a land of date groves. There were also so many wells in Madinah because water was needed to irrigate those palms. People kept wells on their own properties for that purpose. The Well of Ghars lies about five kilometres from Madinah, so its water was brought from there every day in containers for drinking.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'at that time madinah was a city surrounded both within and without by orchards the entire region was filled with date palms which is why it was known as a land of date groves there were also so many wells in madinah because water was needed to irrigate those palms people kept wells on their own properties for that purpose the well of ghars lies about five kilometres from madinah so its water was brought from there every day in containers for drinking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 7, NULL, 'When the passing of the Messenger of God drew near, he instructed that I should be washed with the water of the Well of Ghars and that seven water-skins should be used. Ali عليه السلام carried out the command of the Messenger of God. This also shows that the responsibility for the washing, shrouding, and burial of the Messenger of God rested with Ali عليه السلام, while the Companions of the Messenger were occupied with Saqifah.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'when the passing of the messenger of god drew near he instructed that i should be washed with the water of the well of ghars and that seven water skins should be used ali عليه السلام carried out the command of the messenger of god this also shows that the responsibility for the washing shrouding and burial of the messenger of god rested with ali عليه السلام while the companions of the messenger were occupied with saqifah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 8, NULL, 'When I reached this place for ziyarat, a Sunni Shia scholar had also arrived with his caravan. We spoke for a while, and he said, “Recite something here.” I then recited a qasidah about Ali عليه السلام. People gathered, and a celebration in honour of Amir al-Kainat began at the Well of Ghars. Seeing the well, the excitement, and the gathering, our Sunni brothers could not understand what was happening or why people were repeatedly exclaiming in appreciation. Those poor brothers are in much the same position themselves. They too bow before sacred places and possess an awareness of ziyarat, yet the places connected with the Ahl al-Bayt of the Messenger are being made to disappear. This has been the same dispute for thousands of years.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'when i reached this place for ziyarat a sunni shia scholar had also arrived with his caravan we spoke for a while and he said recite something here i then recited a qasidah about ali عليه السلام people gathered and a celebration in honour of amir al kainat began at the well of ghars seeing the well the excitement and the gathering our sunni brothers could not understand what was happening or why people were repeatedly exclaiming in appreciation those poor brothers are in much the same position themselves they too bow before sacred places and possess an awareness of ziyarat yet the places connected with the ahl al bayt of the messenger are being made to disappear this has been the same dispute for thousands of years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 9, NULL, 'From there I set out again and came toward the house of Imam Zayn al-Abidin عليه السلام, where the orchard attributed to Salman al-Farsi is also located. This orchard and house lie about two kilometres north of Bir Ghars and approximately eight kilometres from Masjid al-Nabawi.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'from there i set out again and came toward the house of imam zayn al abidin عليه السلام where the orchard attributed to salman al farsi is also located this orchard and house lie about two kilometres north of bir ghars and approximately eight kilometres from masjid al nabawi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 10, NULL, 'The situation was that the orchard now found here did not previously exist; the surrounding land was empty. Madinah itself was much the same at that time. If one wished to cultivate crops or plant an orchard, one first had to dig a well. Digging wells in Madinah was no easy task. The ground beneath the mountains is rocky, and breaking through it continuously with tools is extremely arduous work. After coming to Madinah, however, Ali عليه السلام adopted the occupation of digging wells and, alongside it, bringing barren lands under cultivation. He became so proficient at this work that he could dig even the most difficult well within ten days. He would then prepare the land, plant orchards and crops, irrigate them with the water of the well, and afterwards place the land in someone else''s hands. For this reason, Banu Umayyah used to taunt Ali عليه السلام by calling him a digger of wells. In connection with this same activity, he dug seven wells at one place in Wadi Yanbu. Five of them he dedicated as waqf for the benefit of pilgrims entering ihram, while he retained two for his own agricultural work.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the situation was that the orchard now found here did not previously exist the surrounding land was empty madinah itself was much the same at that time if one wished to cultivate crops or plant an orchard one first had to dig a well digging wells in madinah was no easy task the ground beneath the mountains is rocky and breaking through it continuously with tools is extremely arduous work after coming to madinah however ali عليه السلام adopted the occupation of digging wells and alongside it bringing barren lands under cultivation he became so proficient at this work that he could dig even the most difficult well within ten days he would then prepare the land plant orchards and crops irrigate them with the water of the well and afterwards place the land in someone elses hands for this reason banu umayyah used to taunt ali عليه السلام by calling him a digger of wells in connection with this same activity he dug seven wells at one place in wadi yanbu five of them he dedicated as waqf for the benefit of pilgrims entering ihram while he retained two for his own agricultural work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 11, NULL, 'The case of Salman al-Farsi was that his Jewish master did not give him an opportunity to remain in the company of the Messenger of God. For this reason, he was unable to participate even in the battles of Badr and Uhud. Eventually Salman al-Farsi said to the Messenger of God, “O Messenger of God, free me from this Jew.” The Messenger of God told him, “Ask your master the price of your freedom.”', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the case of salman al farsi was that his jewish master did not give him an opportunity to remain in the company of the messenger of god for this reason he was unable to participate even in the battles of badr and uhud eventually salman al farsi said to the messenger of god o messenger of god free me from this jew the messenger of god told him ask your master the price of your freedom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 12, NULL, 'When Salman asked him, the man, out of obstinacy, demanded as the price of freeing Salman from slavery three hundred date palms and forty uqiyyahs of gold. The gold was not difficult to obtain, but the condition involving the orchard was severe. The Messenger of God took Ali عليه السلام and Salman with him and came to this very place, where the orchard still exists today. It lies near the fort of Banu Qurayzah. He marked out one location and told Ali, “Dig a well here,” while telling Salman, “Prepare the land for planting date palms.”', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'when salman asked him the man out of obstinacy demanded as the price of freeing salman from slavery three hundred date palms and forty uqiyyahs of gold the gold was not difficult to obtain but the condition involving the orchard was severe the messenger of god took ali عليه السلام and salman with him and came to this very place where the orchard still exists today it lies near the fort of banu qurayzah he marked out one location and told ali dig a well here while telling salman prepare the land for planting date palms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 13, NULL, 'Both men set to work. When the well had been completed and the land was also ready, the Messenger of God told the Companions, “Help Salman, and provide date-palm saplings for planting in the pits.” The Ansar contributed according to their ability: some gave ten nursery plants, others fifteen, and others different amounts, until the full number of three hundred had been assembled.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'both men set to work when the well had been completed and the land was also ready the messenger of god told the companions help salman and provide date palm saplings for planting in the pits the ansar contributed according to their ability some gave ten nursery plants others fifteen and others different amounts until the full number of three hundred had been assembled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 14, NULL, 'The Messenger of God then returned with Ali and Salman, and the planting began. The Messenger of God would place each nursery plant into the pit with his own hands, Mawla Ali would water it immediately, and Salman would pack the soil around it. In this manner all three hundred plants were completed. They then waited for five months. The purpose of waiting was to ensure that if any tree dried out, a new one could be planted in its place. All the plants remained green. They were then shown to Salman al-Farsi''s master. He accepted them, and Salman al-Farsi was freed.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the messenger of god then returned with ali and salman and the planting began the messenger of god would place each nursery plant into the pit with his own hands mawla ali would water it immediately and salman would pack the soil around it in this manner all three hundred plants were completed they then waited for five months the purpose of waiting was to ensure that if any tree dried out a new one could be planted in its place all the plants remained green they were then shown to salman al farsis master he accepted them and salman al farsi was freed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 15, NULL, 'When the Battle of the Trench took place and Banu Qurayzah, because of their breach of covenant, received their severe punishment, the Messenger of God gave this orchard, this well, and the adjoining farmland into the ownership of Ali. From that time onward, the orchard and well remained with the Ahl al-Bayt of the Messenger, who cultivated the land. Imam Hasan عليه السلام and Imam Husayn عليه السلام also came here and worked, although most of their time of residence was spent at Bayt al-Huzn and Juhaynah. When Imam Zayn al-Abidin عليه السلام returned from Karbala, he settled permanently here rather than in Madinah itself. After him, Imam Baqir عليه السلام, and then Imam Jafar al-Sadiq عليه السلام, likewise remained at this same place.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'when the battle of the trench took place and banu qurayzah because of their breach of covenant received their severe punishment the messenger of god gave this orchard this well and the adjoining farmland into the ownership of ali from that time onward the orchard and well remained with the ahl al bayt of the messenger who cultivated the land imam hasan عليه السلام and imam husayn عليه السلام also came here and worked although most of their time of residence was spent at bayt al huzn and juhaynah when imam zayn al abidin عليه السلام returned from karbala he settled permanently here rather than in madinah itself after him imam baqir عليه السلام and then imam jafar al sadiq عليه السلام likewise remained at this same place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 16, NULL, 'Shias arriving from Kufa, Basrah, Yanbu, and other places would also come and stay here. It pleased me to think that here I too had become a guest of Imam Zayn al-Abidin عليه السلام, Imam Baqir عليه السلام, and Imam Jafar al-Sadiq عليه السلام. Even today I remained here for three or four hours and experienced great tranquillity.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'shias arriving from kufa basrah yanbu and other places would also come and stay here it pleased me to think that here i too had become a guest of imam zayn al abidin عليه السلام imam baqir عليه السلام and imam jafar al sadiq عليه السلام even today i remained here for three or four hours and experienced great tranquillity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 17, NULL, 'Among the date palms are fields of vegetables through which water is flowing. A tube well has been installed in the middle, running at full force, and its water is being directed toward the fields. The atmosphere is exceedingly pleasant. Even now, those who work here and those who sell dates are Shia, although as a precaution they do not openly declare their beliefs to everyone. Yesterday, however, they revealed their views to me. They fed me dajaj mandi and sold me dates that normally cost forty-five riyals per kilogram for thirty riyals. I also bought seedless dates from there.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'among the date palms are fields of vegetables through which water is flowing a tube well has been installed in the middle running at full force and its water is being directed toward the fields the atmosphere is exceedingly pleasant even now those who work here and those who sell dates are shia although as a precaution they do not openly declare their beliefs to everyone yesterday however they revealed their views to me they fed me dajaj mandi and sold me dates that normally cost forty five riyals per kilogram for thirty riyals i also bought seedless dates from there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 18, NULL, 'Throughout Makkah and Madinah, although Imam Husayn عليه السلام, Imam Hasan عليه السلام, and Bibi Fatimah سلام الله عليها lived there, neither their names nor the names of their families are recorded at any place. Even where locations are attributed to them, their names have not been written there. The people living here now merely know that such-and-such a place is historical. There is, however, one half-road named after Ali ibn Abi Talib عليه السلام, and that is all.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'throughout makkah and madinah although imam husayn عليه السلام imam hasan عليه السلام and bibi fatimah سلام الله عليها lived there neither their names nor the names of their families are recorded at any place even where locations are attributed to them their names have not been written there the people living here now merely know that such and such a place is historical there is however one half road named after ali ibn abi talib عليه السلام and that is all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 19, NULL, 'The area behind this orchard and house is known as Qubawali, meaning “the people of Ali.” It is a very large district. Shia Sayyids once lived throughout it. I travelled through it and saw that, across Madinah, they were poor people; the condition of their houses alone makes this apparent. In Madinah and its outskirts, they had effectively been subjected to a social and economic boycott, resembling the boycott in Shib Abi Talib. Ten years ago they sold this entire area into government hands and moved away to a newly established town north of Madinah. In effect, the authorities removed them from here and completely eliminated Shirk from Madinah. The government has begun demolishing the houses in this area so that elite-class hotels may be built for the pilgrims.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the area behind this orchard and house is known as qubawali meaning the people of ali it is a very large district shia sayyids once lived throughout it i travelled through it and saw that across madinah they were poor people the condition of their houses alone makes this apparent in madinah and its outskirts they had effectively been subjected to a social and economic boycott resembling the boycott in shib abi talib ten years ago they sold this entire area into government hands and moved away to a newly established town north of madinah in effect the authorities removed them from here and completely eliminated shirk from madinah the government has begun demolishing the houses in this area so that elite class hotels may be built for the pilgrims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('where-the-caravans-set-forth', 'chapter', 'the reality of biʾr ghars', '15. The Reality of Biʾr Ghars', 20, NULL, 'The few Shias who still remain in Madinah are poor people who work in car workshops. Until one becomes completely certain of them, they appear wholly ordinary and do not disclose their beliefs. The Shias who remain in Madinah are largely concentrated in the area between Bayt al-Huzn and Masjid Bilal. Most of the vehicle workshops are also located there. The Shias of Pakistan and other countries are very fortunate in that they can openly proclaim wilayah. May God grant this opportunity to them as well.', '', NULL, NULL, NULL, NULL, 'where the caravans set forth 15 the reality of bir ghars', 'the few shias who still remain in madinah are poor people who work in car workshops until one becomes completely certain of them they appear wholly ordinary and do not disclose their beliefs the shias who remain in madinah are largely concentrated in the area between bayt al huzn and masjid bilal most of the vehicle workshops are also located there the shias of pakistan and other countries are very fortunate in that they can openly proclaim wilayah may god grant this opportunity to them as well', '');
